  export default "/*\n * Copyright (c) 2023 Unikue Ltd. All rights reserved.\n *\n * Licensed under the MIT License (the \"License\")\n *\n * Permission is hereby granted, free of charge, to any person obtaining a copy\n * of this software and associated documentation files (the \"Software\"), to deal\n * in the Software without restriction, including without limitation the rights\n * to use, copy, modify, merge, publish, distribute, sublicense, and/or sell\n * copies of the Software, and to permit persons to whom the Software is\n * furnished to do so, subject to the following conditions:\n *\n * The above copyright notice and this permission notice shall be included in all\n * copies or substantial portions of the Software.\n */\n\n\nimport React from 'react';\nimport { Avatar, Button, Divider, Space, Tooltip } from 'antd';\nimport { FieldStringOutlined, RedoOutlined } from '@ant-design/icons';\nimport { RemoteField, CommentCard, ConsoleUtils, type RemoteFieldRef } from '@unikue/ant-buddy-pro';\nimport { RandomUtils } from '@unikue/ts-lang-utils';\n\n\nexport default () => {\n    const remoteFieldRef = React.useRef<RemoteFieldRef>(null);\n    const avatars = [\n        'https://gw.alipayobjects.com/zos/rmsportal/BiazfanxmamNRoxxVxka.png',\n        'https://gw.alipayobjects.com/zos/rmsportal/KDpgvguMpGfqaHPjicRK.svg',\n        'https://gw.alipayobjects.com/zos/antfincdn/aPkFc8Sj7n/method-draw-image.svg',\n        'https://zos.alipayobjects.com/rmsportal/jkjgkEfvpUPVyRjUImniVslZfWPnJuuZ.png',\n    ];\n\n    return (\n        <>\n            <Space size='middle'>\n                <Button\n                    icon={<FieldStringOutlined />}\n                    onClick={() => {\n                        ConsoleUtils.logTimestamp(false, false, 'RemoteField', 'outcome = ' + JSON.stringify(remoteFieldRef.current?.getOutcome()));\n                    }}\n                >\n                    打印日志\n                </Button>\n                <Button\n                    icon={<RedoOutlined />}\n                    onClick={() => {\n                        remoteFieldRef.current?.refresh();\n                    }}\n                >\n                    刷新请求\n                </Button>\n            </Space>\n            <Divider />\n            <RemoteField\n                ref={remoteFieldRef}\n                request={async () => {\n                    return {\n                        status: 200,\n                        message: '获取成功',\n                        data: {\n                            avatar: RandomUtils.randomElement(avatars),\n                            author: 'David Hsing',\n                            content: `一只棕色敏捷的狐狸跳过了一只懒洋洋的狗。${RandomUtils.randomString(6)}`,\n                            timestamp: `2024-10-${RandomUtils.randomInteger(10, 32)} ${RandomUtils.randomInteger(10, 24)}:35:36`,\n                        }\n                    };\n                }}\n                render={(outcome: any) => {\n                    if (outcome?.status !== 200) {\n                        return undefined;\n                    }\n                    return (\n                        <CommentCard\n                            avatar={(\n                                <Avatar src={outcome?.data?.avatar} />\n                            )}\n                            author={outcome?.data?.author}\n                            content={outcome?.data?.content}\n                            datetime={(\n                                <Tooltip title={outcome?.data?.timestamp}>\n                                    <span>{RandomUtils.randomInteger(1, 60)} 分钟前</span>\n                                </Tooltip>\n                            )}\n                        />\n                    );\n                }}\n            />\n        </>\n    );\n}\n";;
  